INSERT INTO blog_posts (category_id, title, slug, excerpt, content, author) VALUES
(4, 'Whey Protein: Guia Completo para Iniciantes', 'whey-protein-guia-completo', 'Tudo sobre o suplemento mais popular do mundo fitness', 'Whey protein é proteína do soro do leite, de rápida absorção. Ideal pós-treino para recuperação muscular. Tipos: concentrado, isolado e hidrolisado. Dose: 20-40g por porção. Personal trainers podem registrar suplementação dos alunos na FitTransform para acompanhamento completo.', 'Equipe FitTransform'),
(4, 'Creatina: Benefícios e Como Tomar Corretamente', 'creatina-beneficios-como-tomar', 'Aumente força e ganhos com creatina', 'Creatina aumenta força, massa muscular e recuperação. Dose: 3-5g/dia, sem necessidade de saturação. Pode ser tomada a qualquer hora. É segura e eficaz. Monitore o uso de suplementos dos seus alunos através da FitTransform.', 'Equipe FitTransform'),
(4, 'BCAA: Vale a Pena Suplementar?', 'bcaa-vale-pena-suplementar', 'Aminoácidos de cadeia ramificada explicados', 'BCAAs (leucina, isoleucina, valina) previnem catabolismo e auxiliam recuperação. Útil para treinos em jejum ou dietas restritivas. Se alimentação é adequada, pode não ser necessário. Personal trainers orientam suplementação adequada usando a FitTransform.', 'Equipe FitTransform'),
(4, 'Pré-Treino: Como Escolher o Melhor Para Você', 'pre-treino-escolher-melhor', 'Aumente energia e foco nos treinos', 'Pré-treinos contêm cafeína, beta-alanina, citrulina e outros. Aumentam energia, foco e performance. Evite doses excessivas. Comece com metade da dose. Personal trainers podem recomendar suplementação personalizada através da FitTransform.', 'Equipe FitTransform'),
(4, 'Suplementação para Emagrecimento: O Que Funciona?', 'suplementacao-emagrecimento', 'Suplementos que realmente ajudam na perda de peso', 'Termogênicos, CLA, ômega-3 e fibras podem auxiliar. Nenhum substitui dieta e treino. Cafeína é eficaz para metabolismo. Evite promessas milagrosas. Acompanhe resultados dos alunos com a FitTransform combinando suplementação, treino e nutrição.', 'Equipe FitTransform')
